const allowedPurpose = new Set(['Хочу купити','Хочу орендувати','Хочу продати','Хочу здати в оренду']);
const allowedType = new Set(['Квартира','Будинок','Комерційне приміщення','Земля']);
const required = (name) => { const v = String($json[name] ?? '').trim(); if (!v) throw new Error(`Порожнє обов'язкове поле: ${name}`); return v; };
const full_name = required('ПІБ');
const phone = required('Контактний телефон');
if (!/^\+?[0-9 ()-]{10,20}$/.test(phone)) throw new Error('Неприпустимий формат телефону');
const request_purpose = required('Ціль запиту');
const property_type = required('Тип нерухомості');
if (!allowedPurpose.has(request_purpose)) throw new Error('Неприпустима ціль запиту');
if (!allowedType.has(property_type)) throw new Error('Неприпустимий тип нерухомості');
const property_location = required("Місцезнаходження об'єкта");
const rawDate = required('Бажана дата консультації');
let consultation_date;
let m = rawDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
if (m) consultation_date = rawDate; else { m = rawDate.match(/^(\d{2})[./](\d{2})[./](\d{4})$/); if (!m) throw new Error('Неприпустимий формат дати'); consultation_date = `${m[3]}-${m[2]}-${m[1]}`; }
const parsed = new Date(`${consultation_date}T00:00:00Z`);
if (Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0,10) !== consultation_date) throw new Error('Неіснуюча дата');
const sourceTimestamp = String($json['Отметка времени'] ?? $json['Позначка часу'] ?? $json['Відмітка часу'] ?? $json.Timestamp ?? '').trim();
if (!sourceTimestamp) throw new Error('Тригер не повернув позначку часу');
const source_row_id = `19yHm6hi7G2b8s3y8pFVSoCn8m3HiWJDlFr_CdXMnoUg:567687119:${encodeURIComponent(sourceTimestamp)}:${encodeURIComponent(phone)}:${encodeURIComponent(full_name)}`;
return [{ json: { full_name, phone, request_purpose, property_type, property_location, consultation_date, additional_comments: String($json['Додаткові коментарі'] ?? '').trim() || null, source_row_id } }];

